#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#include "constraint_graph.h"
#include "lv00_internal.h"
#include "normalization.h"
#include "proof.h"
#include "solver.h"
#include "type_system.h"
#include "unify.h"

/* ============== 策略适用场景标记 ============== */

/**
 * @brief 问题特征标志位
 * 用于描述问题的特征，帮助智能选择器匹配合适的策略
 */
typedef enum {
    PROBLEM_FEATURE_NONE = 0,
    PROBLEM_FEATURE_AREA_RELATED = 1 << 0,        /* 涉及面积计算 */
    PROBLEM_FEATURE_ANGLE_RELATED = 1 << 1,       /* 涉及角度关系 */
    PROBLEM_FEATURE_LENGTH_RELATED = 1 << 2,      /* 涉及长度/距离 */
    PROBLEM_FEATURE_PARALLEL = 1 << 3,            /* 涉及平行关系 */
    PROBLEM_FEATURE_PERPENDICULAR = 1 << 4,       /* 涉及垂直关系 */
    PROBLEM_FEATURE_CONGRUENT = 1 << 5,           /* 涉及全等关系 */
    PROBLEM_FEATURE_SIMILAR = 1 << 6,             /* 涉及相似关系 */
    PROBLEM_FEATURE_CIRCLE = 1 << 7,              /* 涉及圆 */
    PROBLEM_FEATURE_POLYNOMIAL = 1 << 8,          /* 可转化为多项式方程 */
    PROBLEM_FEATURE_VECTOR = 1 << 9,              /* 适合向量方法 */
    PROBLEM_FEATURE_COORDINATE = 1 << 10,         /* 适合坐标方法 */
    PROBLEM_FEATURE_HIGH_DIM = 1 << 11,           /* 高维问题 */
    PROBLEM_FEATURE_NON_LINEAR = 1 << 12,         /* 非线性约束 */
    PROBLEM_FEATURE_DEDUCTIVE = 1 << 13,          /* 适合演绎推理 */
    PROBLEM_FEATURE_COMPLEX = 1 << 14             /* 复杂定理 */
} ProblemFeature;

/**
 * @brief 策略成本评估结构
 * 评估每种策略的执行成本和预期效果
 */
typedef struct {
    double time_cost;           /* 时间成本估计（毫秒） */
    double memory_cost;         /* 内存成本估计（KB） */
    double success_probability; /* 成功概率估计（0-1） */
    double complexity_score;    /* 复杂度评分（0-100） */
    int min_dimension;          /* 最小适用维度 */
    int max_dimension;          /* 最大适用维度 */
    ProblemFeature required_features;  /* 必需的问题特征 */
    ProblemFeature preferred_features; /* 偏好的问题特征 */
    ProblemFeature incompatible_features; /* 不兼容的问题特征 */
} StrategyCostProfile;

/**
 * @brief 智能策略选择器上下文
 */
typedef struct {
    StrategyCostProfile profiles[PROOF_STRATEGY_COUNT];
    double feature_weights[16];  /* 各特征的权重 */
    double history_success_rate[PROOF_STRATEGY_COUNT]; /* 历史成功率 */
    int history_attempts[PROOF_STRATEGY_COUNT];        /* 历史尝试次数 */
} StrategySelectorContext;

/* 全局选择器上下文 */
static StrategySelectorContext g_selector_ctx = {0};
static bool g_selector_initialized = false;

/* ============== 内部辅助函数 ============== */

/**
 * @brief 初始化策略选择器
 */
static void init_strategy_selector(void) {
    if (g_selector_initialized) return;
    
    memset(&g_selector_ctx, 0, sizeof(g_selector_ctx));
    
    /* 初始化各策略的成本配置 */
    /* 直接构造法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_DIRECT_CONSTRUCTION] = (StrategyCostProfile){
        .time_cost = 50.0,
        .memory_cost = 100.0,
        .success_probability = 0.7,
        .complexity_score = 20.0,
        .min_dimension = 2,
        .max_dimension = 3,
        .required_features = PROBLEM_FEATURE_NONE,
        .preferred_features = PROBLEM_FEATURE_DEDUCTIVE,
        .incompatible_features = PROBLEM_FEATURE_HIGH_DIM | PROBLEM_FEATURE_NON_LINEAR
    };
    
    /* 面积法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_AREA_METHOD] = (StrategyCostProfile){
        .time_cost = 100.0,
        .memory_cost = 200.0,
        .success_probability = 0.85,
        .complexity_score = 40.0,
        .min_dimension = 2,
        .max_dimension = 3,
        .required_features = PROBLEM_FEATURE_AREA_RELATED,
        .preferred_features = PROBLEM_FEATURE_AREA_RELATED | PROBLEM_FEATURE_LENGTH_RELATED,
        .incompatible_features = PROBLEM_FEATURE_HIGH_DIM
    };
    
    /* Groebner基法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_GROEBNER_BASIS] = (StrategyCostProfile){
        .time_cost = 500.0,
        .memory_cost = 1000.0,
        .success_probability = 0.9,
        .complexity_score = 80.0,
        .min_dimension = 2,
        .max_dimension = 4,
        .required_features = PROBLEM_FEATURE_POLYNOMIAL,
        .preferred_features = PROBLEM_FEATURE_POLYNOMIAL | PROBLEM_FEATURE_COORDINATE,
        .incompatible_features = PROBLEM_FEATURE_HIGH_DIM
    };
    
    /* 向量法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_VECTOR_METHOD] = (StrategyCostProfile){
        .time_cost = 150.0,
        .memory_cost = 300.0,
        .success_probability = 0.75,
        .complexity_score = 50.0,
        .min_dimension = 2,
        .max_dimension = 4,
        .required_features = PROBLEM_FEATURE_VECTOR,
        .preferred_features = PROBLEM_FEATURE_VECTOR | PROBLEM_FEATURE_PARALLEL | PROBLEM_FEATURE_LENGTH_RELATED,
        .incompatible_features = PROBLEM_FEATURE_NONE
    };
    
    /* 全角法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_FULL_ANGLE_METHOD] = (StrategyCostProfile){
        .time_cost = 120.0,
        .memory_cost = 250.0,
        .success_probability = 0.8,
        .complexity_score = 45.0,
        .min_dimension = 2,
        .max_dimension = 2,
        .required_features = PROBLEM_FEATURE_ANGLE_RELATED,
        .preferred_features = PROBLEM_FEATURE_ANGLE_RELATED | PROBLEM_FEATURE_CIRCLE,
        .incompatible_features = PROBLEM_FEATURE_HIGH_DIM | PROBLEM_FEATURE_COORDINATE
    };
    
    /* 演绎数据库法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_DEDUCTIVE_DATABASE] = (StrategyCostProfile){
        .time_cost = 200.0,
        .memory_cost = 500.0,
        .success_probability = 0.65,
        .complexity_score = 60.0,
        .min_dimension = 2,
        .max_dimension = 3,
        .required_features = PROBLEM_FEATURE_DEDUCTIVE,
        .preferred_features = PROBLEM_FEATURE_DEDUCTIVE | PROBLEM_FEATURE_CONGRUENT | PROBLEM_FEATURE_SIMILAR,
        .incompatible_features = PROBLEM_FEATURE_NON_LINEAR
    };
    
    /* 坐标法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_COORDINATE] = (StrategyCostProfile){
        .time_cost = 300.0,
        .memory_cost = 400.0,
        .success_probability = 0.7,
        .complexity_score = 55.0,
        .min_dimension = 2,
        .max_dimension = 3,
        .required_features = PROBLEM_FEATURE_COORDINATE,
        .preferred_features = PROBLEM_FEATURE_COORDINATE | PROBLEM_FEATURE_LENGTH_RELATED,
        .incompatible_features = PROBLEM_FEATURE_HIGH_DIM
    };
    
    /* Oracle法 */
    g_selector_ctx.profiles[PROOF_STRATEGY_ORACLE] = (StrategyCostProfile){
        .time_cost = 1000.0,
        .memory_cost = 2000.0,
        .success_probability = 0.95,
        .complexity_score = 90.0,
        .min_dimension = 2,
        .max_dimension = 10,
        .required_features = PROBLEM_FEATURE_NONE,
        .preferred_features = PROBLEM_FEATURE_COMPLEX | PROBLEM_FEATURE_HIGH_DIM | PROBLEM_FEATURE_NON_LINEAR,
        .incompatible_features = PROBLEM_FEATURE_NONE
    };
    
    /* 初始化特征权重 */
    for (int i = 0; i < 16; i++) {
        g_selector_ctx.feature_weights[i] = 1.0;
    }
    
    g_selector_initialized = true;
}

/**
 * @brief 分析问题特征
 * 根据约束图和命题分析问题的特征
 */
static ProblemFeature analyze_problem_features(const ConstraintGraph *graph, const Proposition *prop) {
    ProblemFeature features = PROBLEM_FEATURE_NONE;
    
    if (!graph && !prop) return features;
    
    /* 分析约束图 */
    if (graph) {
        /* 检查约束类型 */
        for (int i = 0; i < graph->constraint_count; i++) {
            Constraint *c = graph->constraints[i];
            if (!c) continue;
            
            switch (c->type) {
                case CONSTRAINT_TYPE_AREA:
                    features |= PROBLEM_FEATURE_AREA_RELATED;
                    break;
                case CONSTRAINT_TYPE_ANGLE:
                    features |= PROBLEM_FEATURE_ANGLE_RELATED;
                    break;
                case CONSTRAINT_TYPE_DISTANCE:
                case CONSTRAINT_TYPE_LENGTH:
                    features |= PROBLEM_FEATURE_LENGTH_RELATED;
                    break;
                case CONSTRAINT_TYPE_PARALLEL:
                    features |= PROBLEM_FEATURE_PARALLEL;
                    break;
                case CONSTRAINT_TYPE_PERPENDICULAR:
                    features |= PROBLEM_FEATURE_PERPENDICULAR;
                    break;
                case CONSTRAINT_TYPE_CIRCLE:
                    features |= PROBLEM_FEATURE_CIRCLE;
                    break;
                default:
                    break;
            }
        }
        
        /* 检查维度 */
        if (graph->dimension > 3) {
            features |= PROBLEM_FEATURE_HIGH_DIM;
        }
        
        /* 检查复杂度 */
        if (graph->constraint_count > 20 || graph->node_count > 30) {
            features |= PROBLEM_FEATURE_COMPLEX;
        }
        
        /* 检查是否可转化为多项式 */
        bool has_polynomial = true;
        for (int i = 0; i < graph->constraint_count; i++) {
            Constraint *c = graph->constraints[i];
            if (c && c->type == CONSTRAINT_TYPE_NON_LINEAR) {
                has_polynomial = false;
                features |= PROBLEM_FEATURE_NON_LINEAR;
                break;
            }
        }
        if (has_polynomial && graph->constraint_count > 0) {
            features |= PROBLEM_FEATURE_POLYNOMIAL;
        }
    }
    
    /* 分析命题 */
    if (prop && prop->pattern) {
        /* 检查命题名称和描述 */
        if (prop->name) {
            if (strstr(prop->name, "area") || strstr(prop->name, "Area")) {
                features |= PROBLEM_FEATURE_AREA_RELATED;
            }
            if (strstr(prop->name, "angle") || strstr(prop->name, "Angle")) {
                features |= PROBLEM_FEATURE_ANGLE_RELATED;
            }
            if (strstr(prop->name, "vector") || strstr(prop->name, "Vector")) {
                features |= PROBLEM_FEATURE_VECTOR;
            }
            if (strstr(prop->name, "coordinate") || strstr(prop->name, "Coordinate")) {
                features |= PROBLEM_FEATURE_COORDINATE;
            }
        }
        
        if (prop->description) {
            if (strstr(prop->description, "area")) {
                features |= PROBLEM_FEATURE_AREA_RELATED;
            }
            if (strstr(prop->description, "angle")) {
                features |= PROBLEM_FEATURE_ANGLE_RELATED;
            }
        }
    }
    
    return features;
}

/**
 * @brief 计算策略匹配分数
 * 根据问题特征和策略配置计算匹配分数
 */
static double calculate_strategy_match_score(ProofStrategyType type, 
                                              ProblemFeature features,
                                              int dimension) {
    if (!g_selector_initialized) {
        init_strategy_selector();
    }
    
    const StrategyCostProfile *profile = &g_selector_ctx.profiles[type];
    double score = 0.0;
    
    /* 检查维度兼容性 */
    if (dimension < profile->min_dimension || dimension > profile->max_dimension) {
        return -1.0; /* 不兼容 */
    }
    
    /* 检查必需特征 */
    if ((features & profile->required_features) != profile->required_features) {
        return -1.0; /* 缺少必需特征 */
    }
    
    /* 检查不兼容特征 */
    if (features & profile->incompatible_features) {
        return -1.0; /* 存在不兼容特征 */
    }
    
    /* 计算偏好特征匹配分数 */
    ProblemFeature matched = features & profile->preferred_features;
    int matched_count = 0;
    for (int i = 0; i < 16; i++) {
        if (matched & (1 << i)) {
            matched_count++;
            score += g_selector_ctx.feature_weights[i] * 10.0;
        }
    }
    
    /* 考虑历史成功率 */
    if (g_selector_ctx.history_attempts[type] > 0) {
        double hist_rate = g_selector_ctx.history_success_rate[type];
        score += hist_rate * 20.0;
    } else {
        /* 没有历史记录时，使用默认成功概率 */
        score += profile->success_probability * 15.0;
    }
    
    /* 考虑复杂度匹配 */
    int feature_count = 0;
    for (int i = 0; i < 16; i++) {
        if (features & (1 << i)) feature_count++;
    }
    double complexity_diff = fabs(profile->complexity_score - feature_count * 5.0);
    score -= complexity_diff * 0.5;
    
    /* 考虑时间成本 */
    score -= profile->time_cost * 0.01;
    
    return score;
}

/**
 * @brief 更新策略历史记录
 */
static void update_strategy_history(ProofStrategyType type, bool success) {
    if (!g_selector_initialized) {
        init_strategy_selector();
    }
    
    g_selector_ctx.history_attempts[type]++;
    
    double old_rate = g_selector_ctx.history_success_rate[type];
    double new_rate = (old_rate * (g_selector_ctx.history_attempts[type] - 1) + (success ? 1.0 : 0.0)) 
                      / g_selector_ctx.history_attempts[type];
    g_selector_ctx.history_success_rate[type] = new_rate;
}

/**
 * @brief 默认适用性检查 —— 直接构造法适用于所有命题
 */
static bool default_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                        const Proposition *prop) {
    (void) mse;
    /* 直接构造法总是可用 —— 只要图和命题非空 */
    return (graph != NULL) && (prop != NULL);
}

/**
 * @brief 面积法适用性检查 —— 检查是否涉及面积命题
 */
static bool area_method_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                            const Proposition *prop) {
    (void) mse;
    if (prop == NULL)
        return false;
    
    ProblemFeature features = analyze_problem_features(graph, prop);
    return (features & PROBLEM_FEATURE_AREA_RELATED) != 0;
}

/**
 * @brief Groebner基法适用性检查 —— 检查是否有代数方程可求解
 */
static bool groebner_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                         const Proposition *prop) {
    (void) mse;
    (void) prop;
    if (graph == NULL)
        return false;
    
    ProblemFeature features = analyze_problem_features(graph, prop);
    return (features & PROBLEM_FEATURE_POLYNOMIAL) != 0 && 
           !(features & PROBLEM_FEATURE_HIGH_DIM);
}

/**
 * @brief 向量法适用性检查
 */
static bool vector_method_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                              const Proposition *prop) {
    (void) mse;
    if (!graph && !prop) return false;
    
    ProblemFeature features = analyze_problem_features(graph, prop);
    return (features & PROBLEM_FEATURE_VECTOR) != 0 ||
           ((features & PROBLEM_FEATURE_PARALLEL) && (features & PROBLEM_FEATURE_LENGTH_RELATED));
}

/**
 * @brief 全角法适用性检查
 */
static bool full_angle_method_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                                  const Proposition *prop) {
    (void) mse;
    if (!graph && !prop) return false;
    
    ProblemFeature features = analyze_problem_features(graph, prop);
    if (features & PROBLEM_FEATURE_HIGH_DIM) return false;
    
    return (features & PROBLEM_FEATURE_ANGLE_RELATED) != 0 ||
           (features & PROBLEM_FEATURE_CIRCLE) != 0;
}

/**
 * @brief 演绎数据库法适用性检查
 */
static bool deductive_database_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                                   const Proposition *prop) {
    (void) mse;
    if (!graph && !prop) return false;
    
    ProblemFeature features = analyze_problem_features(graph, prop);
    return (features & PROBLEM_FEATURE_DEDUCTIVE) != 0 &&
           !(features & PROBLEM_FEATURE_NON_LINEAR);
}

/**
 * @brief 坐标法适用性检查
 */
static bool coordinate_method_applicability_check(const ProofMultiStrategy *mse, const ConstraintGraph *graph,
                                                  const Proposition *prop) {
    (void) mse;
    if (!graph && !prop) return false;
    
    ProblemFeature features = analyze_problem_features(graph, prop);
    return (features & PROBLEM_FEATURE_COORDINATE) != 0 ||
           ((features & PROBLEM_FEATURE_LENGTH_RELATED) && !(features & PROBLEM_FEATURE_HIGH_DIM));
}

